{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"CA","category":"application_screening_fees","lifecycle":"enacted","title":"California tenant screening fee cap (2026)","requirement":"A landlord may charge no more than the maximum screening fee ($68.96 for 2026), may not charge a fee when no unit is available, and must provide a copy of any credit report, a receipt, an itemized list and a refund of unused fees.","key_value":"$68.96 for 2026","coverage_conditions":"Limits on the amount and uses of tenant screening and application fees apply under state and local law to residential rental applicants.","applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":"2026","valid_through":"2026","citation":"Cal. Civ. Code § 1950.6","quoted_span":"The maximum tenant screening fee for 2026 is $68.96","interaction":null,"relations":[],"confidence":0.7,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"CA","category":"screening_restrictions","lifecycle":"enacted","title":"California reusable screening report and application-review order rules","requirement":"A landlord must use a reusable screening report a prospective tenant provides. A landlord not returning screening fees must review applications in the order received, give the unit to the first qualified applicant and not charge applicants not considered.","key_value":null,"coverage_conditions":"Prospective residential rental tenants in California under the state screening law; reusable screening reports must be accepted.","applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"Cal. Civ. Code § 1950.6","quoted_span":"If the tenant provides a reusable screening report, the landlord must use it.","interaction":null,"relations":[],"confidence":0.7,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"Berkeley, CA","category":"application_screening_fees","lifecycle":"enacted","title":"Berkeley tenant screening fee disclosure and non-refundable application fee rules","requirement":"An owner who charges a screening fee must give the applicant a tenant screening fee rights statement and the state maximum fee cap before collecting the fee, and may not charge an existing tenant a non-refundable fee to renew a tenancy or change roommates.","key_value":null,"coverage_conditions":"Applies to all residential rental agreements in Berkeley, regardless of lease language; violating lease provisions are unenforceable.","applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":null,"penalty":"Any provision of an existing rental agreement or lease that violates the chapter is unenforceable.","effective_date":null,"valid_through":null,"citation":"Berkeley Mun. Code ch. 13.78","quoted_span":"the owner must provide, either in the rental application or in a separate disclosure before receiving the fee, a clear and conspicuous tenant screening fee rights statement and a statement of the maximum fee cap permitted under California Civil Code Section 1950.6(b)","interaction":"Requires disclosure of the state screening fee cap under California Civil Code Section 1950.6(b).","relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D005-01","n_rules":3,"note":null}

